awareness_metrics = {
    "phishing_click_rate": 0.03,
    "training_completion": 0.98,
    "incident_reports": 24,
    "policy_violations": 2
}
for metric, value in awareness_metrics.items():
    if isinstance(value, float):
        print(f"{metric}: {value*100:.1f}%")
    else:
        print(f"{metric}: {value}")
